    def analyze_sentiment(self, text):
        """Valódi szövegelemzés"""
        if HAS_TEXTBLOB:
            try:
                blob = TextBlob(text)
                polarity = blob.sentiment.polarity
                subjectivity = blob.sentiment.subjectivity

                if polarity > 0.1:
                    sentiment = "pozitív"
                elif polarity < 0.1:
                    sentiment = "negatív"
                else:
                    sentiment = "semleges"

                return {
                    "sentiment": sentiment,
                    "polarity": round(polarity, 3),
                    "subjectivity": round(subjectivity, 3),
                    "confidence": round(abs(polarity), 3)
                }
            except:
                pass

         Fallback sentiment analysis
        text_lower = text.lower()
        positive_words = ['jó', 'remek', 'szuper', 'kiváló', 'fantasztikus', 'szeretek', 'imádom', 'boldog']
        negative_words = ['rossz', 'szörnyű', 'utálom', 'nem tetszik', 'problém', 'hiba', 'szomorú']

        pos_count = sum(1 for word in positive_words if word in text_lower)
        neg_count = sum(1 for word in negative_words if word in text_lower)

        if pos_count > neg_count:
            sentiment = "pozitív"
            polarity = 0.5
        elif neg_count > pos_count:
            sentiment = "negatív" 
            polarity = 0.5
        else:
            sentiment = "semleges"
            polarity = 0.0

        return {
            "sentiment": sentiment,
            "polarity": polarity,
            "subjectivity": 0.5,
            "confidence": abs(polarity)
        }

    def extract_keywords(self, text):
        """Kulcsszavak kinyerése valódi NLPvel"""
         Tisztítás és tokenizálás
        text = re.sub(r'[^\w\s]', '', text.lower())
        words = text.split()

         Magyar stopszavak
        stop_words = {'a', 'az', 'egy', 'és', 'van', 'volt', 'lesz', 'hogy', 'ez', 'azt', 
                     'ezt', 'vagy', 'de', 'ha', 'is', 'nem', 'csak', 'még', 'már', 'mint',
                     'fel', 'le', 'ki', 'be', 'el', 'meg', 'át', 'vissza', 'ide', 'oda'}

         Szűrés és súlyozás
        filtered_words = [word for word in words if len(word) > 2 and word not in stop_words]
        word_freq = Counter(filtered_words)

         TFIDF szerű súlyozás
        total_words = len(filtered_words)
        keywords = []
        for word, freq in word_freq.most_common(5):
            tf = freq / total_words
             Egyszerűsített IDF
            idf = math.log(total_words / freq) if freq > 0 else 0
            score = tf  idf
            keywords.append({"word": word, "frequency": freq, "score": round(score, 3)})

        return keywords

    def find_knowledge_domain(self, text):
        """Tudásterület azonosítása"""
        text_lower = text.lower()
        domain_scores = {}

        for domain, categories in self.knowledge_base.items():
            score = 0
            for category, keywords in categories.items():
                for keyword in keywords:
                    if keyword in text_lower:
                        score += 1
            domain_scores[domain] = score

        if domain_scores:
            best_domain = max(domain_scores, key=domain_scores.get)
            if domain_scores[best_domain] > 0:
                return best_domain, domain_scores[best_domain]

        return "general", 0

